/**
 * generated by stackra gen from services/commerce/.stackra/app-manifest.json and the figentra-os
 * manifests pinned in stackra-manifests.lock.yaml (billing@8e1b3d2, content@4a9c7f1,
 * experience@b82d913, marketing@c3d8e07), filtered to the `public` area — do not edit
 * Purpose: typed descriptors for every consumed public query, action and refusal: what loaders,
 *          submits, blocks (`accepts`) and sitemap sources name.
 * Boundary: descriptors only; `gen/clients.server.ts` performs the call. The storefront projection
 *           of a product is the public area's view of the catalogue, richer than the console's.
 * Runtime: isomorphic
 */
import { actionRef, queryRef, refusalRef } from "@stackra/clients";
import { COLOR_TOKENS } from "@stackra/brand";
import { ContentEntryType } from "@stackra/content";
import { HttpMethod } from "@stackra/contracts";
import { LocaleValue } from "@stackra/i18n";
import { Risk } from "@stackra/iam";
import { z } from "@stackra/schema";
import { I18n } from "#stackra/i18n";

/**
 * The newest date listed in the producer's VersioningConfig at gen time; identical in every app of
 * the workspace.
 */
export const apiVersion = "2027-03-01" as const;

/** `#/schemas/Image`: a media URL the image-variant helper can resize. */
export const Image = z.object({ url: z.string(), alt: z.string().nullable() });

/** `#/schemas/StorefrontVariant`. */
export const StorefrontVariant = z.object({
  id: z.string(),
  sku: z.string(),
  priceMinor: z.number().int(),
  inStock: z.boolean(),
  options: z.record(z.string(), z.string()),
});

/** `#/schemas/StorefrontProductCard`: one product in a grid. */
export const StorefrontProductCard = z.object({
  id: z.string(),
  title: z.string(),
  slug: z.string(),
  priceMinor: z.number().int(),
  currency: z.string(),
  image: Image.nullable(),
  inStock: z.boolean(),
});

/** `#/schemas/StorefrontProductView`: one product's page. */
export const StorefrontProductView = z.object({
  id: z.string(),
  title: z.string(),
  slug: z.string(),
  currency: z.string(),
  inStock: z.boolean(),
  images: z.array(Image),
  description: z.unknown(),
  variants: z.array(StorefrontVariant),
  seo: z.object({
    title: z.string().nullable(),
    description: z.string().nullable(),
    noindex: z.boolean(),
  }),
  collections: z.array(z.object({ title: z.string(), slug: z.string() })),
});

/** `#/schemas/StorefrontProductPage`: a cursor page of cards. */
export const StorefrontProductPage = z.object({
  items: z.array(StorefrontProductCard),
  nextCursor: z.string().optional(),
  hasMore: z.boolean(),
});

/** `#/schemas/Entry`: one content entry; fields are the content type's plain strings. */
export const Entry = z.object({ id: z.string(), fields: z.record(z.string(), z.string()) });

/** `#/schemas/Plan`: one rung of a plan ladder, priced in the request's market. */
export const Plan = z.object({
  key: z.string(),
  name: z.string(),
  prices: z.object({ month: z.number().int().nullable(), year: z.number().int().nullable() }),
  currency: z.string(),
  limits: z.array(z.string()),
  entitlements: z.array(z.string()),
  highlighted: z.boolean(),
});

/**
 * `#/schemas/Site`: the tenant site a host resolves to; `brand` overrides any subset of the brand
 * tokens.
 */
export const Site = z.object({
  id: z.string(),
  name: z.string(),
  market: z.object({ key: z.string(), currency: z.string() }),
  indexable: z.boolean(),
  brand: z.partialRecord(
    z.enum(Object.keys(COLOR_TOKENS) as [keyof typeof COLOR_TOKENS]),
    z.string(),
 ),
});

/** `#/schemas/PublishedDocument`: a tenant's published L2 document and its SEO fields. */
export const PublishedDocument = z.object({
  key: z.string(),
  version: z.number().int(),
  root: z.unknown(),
  seo: z.object({
    title: z.string(),
    description: z.string().nullable(),
    noindex: z.boolean(),
    image: z.string().nullable(),
  }),
});

/** `#/schemas/StorefrontListFilter`: cursor, limit, an optional phrase and collection slug. */
export const StorefrontListFilter = z.object({
  cursor: z.string().optional(),
  limit: z.number().int().min(1).max(100).default(20),
  search: z.string().max(200).optional(),
  collection: z.string().max(200).optional(),
});

/** `#/schemas/SearchProductsInput`: the search phrase, an optional collection slug, cursor and limit. */
export const SearchProductsInput = z.object({
  q: z.string().min(2).max(64),
  collection: z.string().max(200).optional(),
  cursor: z.string().optional(),
  limit: z.number().int().min(1).max(100).default(20),
});

/** Commerce, public area. */
export const Commerce = {
  queries: {
    ListStorefrontProducts: queryRef("catalogue.product.list_storefront", {
      input: StorefrontListFilter,
      output: StorefrontProductPage,
      http: { method: HttpMethod.Get, path: "/public/products" },
    }),
    SearchProducts: queryRef("catalogue.product.search", {
      input: SearchProductsInput,
      output: StorefrontProductPage,
      http: { method: HttpMethod.Get, path: "/public/products/search" },
    }),
    GetProductBySlug: queryRef("catalogue.product.get_by_slug", {
      input: z.object({ slug: z.string() }),
      output: StorefrontProductView,
      http: { method: HttpMethod.Get, path: "/public/products/by-slug/:slug" },
    }),
  },
  refusals: {
    product_not_found: refusalRef("catalogue.product_not_found", {
      message: I18n.catalogue.refusals.product_not_found,
    }),
  },
} as const;

/** Billing, public area. */
export const Billing = {
  queries: {
    ListPlans: queryRef("billing.catalog.plan.list", {
      input: z.object({ product: z.string() }),
      output: z.object({ trialDays: z.number().int(), plans: z.array(Plan) }),
      http: { method: HttpMethod.Get, path: "/public/plans" },
    }),
  },
} as const;

/** Content, public area. */
export const Content = {
  queries: {
    ListEntries: queryRef("content.entry.list", {
      input: z.object({
        siteId: z.string(),
        type: ContentEntryType.schema,
        limit: z.number().int().optional(),
      }),
      output: z.object({ entries: z.array(Entry) }),
      http: { method: HttpMethod.Get, path: "/public/entries" },
    }),
  },
} as const;

/** Experience, public area: sites, documents, SEO. */
export const Experience = {
  queries: {
    ResolveSite: queryRef("sites.site.resolve", {
      input: z.object({ host: z.string() }),
      output: Site.nullable(),
      http: { method: HttpMethod.Get, path: "/public/sites/resolve" },
    }),
    GetSite: queryRef("sites.site.get", {
      input: z.object({ siteId: z.string() }),
      output: Site.nullable(),
      http: { method: HttpMethod.Get, path: "/public/sites/:siteId" },
    }),
    GetDocument: queryRef("experience.document.get", {
      input: z.union([z.object({ key: z.string() }), z.object({ path: z.string() })]),
      output: PublishedDocument.nullable(),
      http: { method: HttpMethod.Get, path: "/public/experience/documents" },
    }),
    GetPagesSitemap: queryRef("pages.sitemap.get", {
      input: z.object({ siteId: z.string() }),
      output: z.object({
        entries: z.array(z.object({ path: z.string(), updatedAt: z.string().optional() })),
      }),
      http: { method: HttpMethod.Get, path: "/public/pages/sitemap" },
    }),
    ResolveRedirect: queryRef("seo.redirect.resolve", {
      input: z.object({ host: z.string(), path: z.string() }),
      output: z
        .object({ to: z.string(), status: z.union([z.literal(301), z.literal(302)]) })
        .nullable(),
      http: { method: HttpMethod.Get, path: "/public/seo/redirects/resolve" },
    }),
  },
  actions: {
    RecordNotFound: actionRef("seo.not_found.record", {
      input: z.object({ host: z.string(), path: z.string(), referrer: z.string().optional() }),
      output: z.object({}),
      http: { method: HttpMethod.Post, path: "/public/seo/not-found" },
      risk: Risk.L0,
    }),
  },
  refusals: {
    not_found: refusalRef("experience.not_found", { message: I18n.experience.refusals.not_found }),
  },
} as const;

/** Marketing, public area. */
export const Marketing = {
  actions: {
    CreateLead: actionRef("leads.lead.create", {
      input: z.object({
        name: z.string(),
        email: z.string(),
        company: z.string().optional(),
        message: z.string(),
        consent: z.literal(true),
        locale: LocaleValue,
        captchaToken: z.string(),
      }),
      output: z.object({ leadId: z.string() }),
      http: { method: HttpMethod.Post, path: "/public/leads" },
      risk: Risk.L0,
    }),
  },
  refusals: {
    rate_limited: refusalRef("leads.rate_limited", { message: I18n.leads.refusals.rate_limited }),
    captcha_failed: refusalRef("leads.captcha_failed", {
      message: I18n.leads.refusals.captcha_failed,
    }),
  },
} as const;
